INSERT INTO sources (id, name, url, license, cleared_at, notes) VALUES ('editorial-original', '2yolks editorial (original wording, untested drafts)', 'internal:editorial-original', 'internal-original', NULL, 'Original text written for 2yolks from standard, widely documented techniques. NOT kitchen-tested. No images. No copied expression from any site. Stays draft until a person cooks and signs off each recipe.');
INSERT INTO recipes (id, source_id, origin_country) VALUES ('w1-golumpki-soup', 'editorial-original', 'pl');
INSERT INTO recipe_locales (recipe_id, country, lang, title, slug, intro, ingredients_json, steps_json, status) VALUES ('w1-golumpki-soup', 'us', 'en', 'Golumpki (Unstuffed Cabbage Roll) Soup', 'golumpki-soup', 'All the flavors of Polish stuffed cabbage rolls in one pot, with no rolling. Serves 6. About 25 minutes of work and 70 minutes total. Draft: not yet tested in a kitchen.', '["1 tbsp olive oil","1 lb (450 g) ground beef, or half beef and half pork","1 medium onion, diced","3 garlic cloves, minced","1 tbsp tomato paste","1 tsp sweet paprika","1 small green cabbage (about 1.5 lb / 700 g), cored and cut into 1-inch (2.5 cm) pieces","1 can (28 oz / 800 g) crushed tomatoes","4 cups (1 L) beef broth","1/2 cup (100 g) long-grain white rice, uncooked","1 bay leaf","1 tsp salt, plus more to taste","1/2 tsp black pepper","1 tbsp apple cider vinegar","Chopped parsley, to serve"]', '["Heat the oil in a large pot over medium-high heat. Add the meat and cook, breaking it up, 6 to 8 minutes, until no pink remains and it reaches 160°F (71°C). Spoon off excess fat.","Add the onion and cook 4 minutes until soft. Stir in the garlic, tomato paste and paprika and cook 1 minute.","Add the cabbage, crushed tomatoes, broth, bay leaf, salt and pepper. Bring to a boil, then lower the heat, cover and simmer 15 minutes.","Stir in the rice. Cover and simmer 20 minutes more, until the rice and cabbage are tender. If the soup gets too thick, add 1/2 cup (120 ml) water.","Remove the bay leaf. Stir in the vinegar, taste, and add salt if needed. Serve hot with parsley. Refrigerate leftovers within 2 hours."]', 'draft');
INSERT INTO recipes (id, source_id, origin_country) VALUES ('w1-pork-cabbage-potstickers', 'editorial-original', 'cn');
INSERT INTO recipe_locales (recipe_id, country, lang, title, slug, intro, ingredients_json, steps_json, status) VALUES ('w1-pork-cabbage-potstickers', 'us', 'en', 'Pork and Cabbage Potstickers', 'pork-cabbage-potstickers', 'Crisp-bottomed dumplings with a juicy pork and cabbage filling. Makes about 30 and serves 4 to 6. About 60 minutes. Draft: not yet tested in a kitchen.', '["3 cups (about 250 g) finely chopped napa cabbage","1 tsp salt","1 lb (450 g) ground pork","3 scallions, thinly sliced","1 tbsp grated fresh ginger","2 garlic cloves, minced","1 tbsp soy sauce","1 tbsp Shaoxing wine or dry sherry","1 tsp toasted sesame oil","1/2 tsp white pepper","1 tbsp cornstarch","30 to 36 round dumpling wrappers (one 12 to 14 oz package)","2 tbsp neutral oil, for pan-frying","1 cup (240 ml) water, for steaming, used in batches","Dipping sauce: 3 tbsp soy sauce, 1 tbsp rice vinegar, 1 tsp sesame oil"]', '["Toss the cabbage with the salt and let it sit 15 minutes. Squeeze it dry in a clean towel.","Mix the cabbage with the pork, scallions, ginger, garlic, soy sauce, wine, sesame oil, white pepper and cornstarch. Stir in one direction for about 1 minute until the mixture holds together.","To check the seasoning, cook a small spoonful in a pan until no pink remains (160°F / 71°C), taste, and adjust.","Put a heaped tablespoon of filling in the center of a wrapper. Wet the edge, fold in half and pleat to seal. Keep filled dumplings covered with a damp towel.","Heat 2 teaspoons of oil in a large nonstick skillet with a lid over medium-high heat. Add about 10 dumplings flat side down and cook 2 to 3 minutes until golden underneath.","Add 1/3 cup (80 ml) water, cover and steam 6 to 7 minutes, until the filling reaches 160°F (71°C). Uncover and cook 1 minute until the water is gone. Repeat with the remaining dumplings in two more batches.","Stir the dipping sauce ingredients together and serve with the hot dumplings."]', 'draft');
INSERT INTO recipes (id, source_id, origin_country) VALUES ('w1-pozole-rojo', 'editorial-original', 'mx');
INSERT INTO recipe_locales (recipe_id, country, lang, title, slug, intro, ingredients_json, steps_json, status) VALUES ('w1-pozole-rojo', 'mx', 'es', 'Pozole rojo de cerdo', 'pozole-rojo-de-cerdo', 'Caldo de maíz cacahuazintle con cerdo y salsa de chiles guajillo y ancho. Rinde 6 a 8 porciones. Unas 2 horas y 30 minutos en total. Borrador: aún no probado en cocina.', '["1 kg de espaldilla de cerdo, en trozos de 4 cm","2.5 litros de agua","1/2 cebolla","4 dientes de ajo","2 hojas de laurel","2 cucharaditas de sal, y más al gusto","4 chiles guajillo, sin rabo, semillas ni venas","2 chiles ancho, sin rabo, semillas ni venas","1/4 de cebolla","2 dientes de ajo","1 cucharadita de orégano mexicano","1/4 de cucharadita de comino molido","800 g de maíz cacahuazintle precocido (cocido y escurrido)","Para servir: lechuga o repollo picado, rábanos en rodajas, cebolla picada, orégano, limón y tostadas"]', '["Pon el cerdo en una olla grande con el agua, la 1/2 cebolla, los 4 dientes de ajo, el laurel y la sal. Hierve y retira la espuma de la superficie.","Baja el fuego, tapa y cuece 1 hora y 15 minutos a 1 hora y 30 minutos, hasta que la carne esté muy suave.","Mientras tanto, tuesta los chiles en un comal 20 a 30 segundos por lado, sin quemarlos. Remójalos 15 minutos en agua caliente que los cubra.","Licúa los chiles con 1 taza (250 ml) de su agua de remojo, el 1/4 de cebolla, los 2 dientes de ajo, el orégano y el comino hasta que quede liso. Cuela la salsa.","Escurre y enjuaga el maíz. Agrégalo a la olla junto con la salsa colada.","Hierve suavemente 30 minutos, hasta que el caldo tome sabor. Prueba y ajusta la sal.","Sirve caliente con lechuga o repollo, rábano, cebolla, orégano, limón y tostadas."]', 'draft');
INSERT INTO recipes (id, source_id, origin_country) VALUES ('w1-enchiladas-rojas-pollo', 'editorial-original', 'mx');
INSERT INTO recipe_locales (recipe_id, country, lang, title, slug, intro, ingredients_json, steps_json, status) VALUES ('w1-enchiladas-rojas-pollo', 'mx', 'es', 'Enchiladas rojas de pollo', 'enchiladas-rojas-de-pollo', 'Tortillas de maíz bañadas en salsa roja de guajillo y ancho, rellenas de pollo deshebrado. Rinde 4 porciones (12 enchiladas). Unos 55 minutos. Borrador: aún no probado en cocina.', '["2 pechugas de pollo (unos 600 g)","1/2 cebolla","2 dientes de ajo","1 cucharadita de sal, y más al gusto","5 chiles guajillo, sin rabo, semillas ni venas","2 chiles ancho, sin rabo, semillas ni venas","3 jitomates guaje (roma)","1/4 de cebolla","1 diente de ajo","1 cucharada de aceite, para freír la salsa","1/2 taza (120 ml) de aceite, para pasar las tortillas","12 tortillas de maíz","150 g de queso fresco desmoronado","1/2 taza (120 ml) de crema","Cebolla picada y lechuga, para servir"]', '["Pon el pollo en una olla con agua que lo cubra, la 1/2 cebolla, 2 dientes de ajo y la cucharadita de sal. Hierve, baja el fuego y cuece tapado 18 a 20 minutos, hasta que el centro llegue a 74°C. Reserva 1 taza (250 ml) del caldo. Deshebra el pollo.","Mientras tanto, tuesta los chiles en un comal 20 a 30 segundos por lado. Remójalos 15 minutos en agua caliente. Hierve los jitomates 5 minutos.","Licúa los chiles escurridos con los jitomates, el 1/4 de cebolla, 1 diente de ajo, 1 taza del caldo reservado y una pizca de sal. Cuela.","Calienta 1 cucharada de aceite en una sartén, vierte la salsa y cocina 5 minutos a fuego medio. Ajusta la sal.","Calienta 1/2 taza de aceite en otra sartén. Pasa cada tortilla 5 segundos por lado en el aceite caliente y luego por la salsa.","Rellena cada tortilla con pollo, enróllala y acomódala en un platón. Baña con la salsa restante.","Sirve con queso fresco, crema, cebolla y lechuga."]', 'draft');
INSERT INTO recipes (id, source_id, origin_country) VALUES ('w1-tacos-birria-res', 'editorial-original', 'mx');
INSERT INTO recipe_locales (recipe_id, country, lang, title, slug, intro, ingredients_json, steps_json, status) VALUES ('w1-tacos-birria-res', 'mx', 'es', 'Tacos de birria de res con consomé', 'tacos-de-birria-de-res', 'Res cocida lentamente en una salsa de chiles, servida en tacos dorados con queso y un consomé para mojar. Rinde unos 16 tacos. Unas 4 horas en total, casi todo en el horno. Borrador: aún no probado en cocina.', '["1.2 kg de falda o aguayón de res, en 4 trozos grandes","5 chiles guajillo, sin rabo, semillas ni venas","2 chiles ancho, sin rabo, semillas ni venas","3 chiles de árbol secos (opcional, para más picante)","3 jitomates guaje (roma)","1/2 cebolla","5 dientes de ajo","2 cucharadas de vinagre de manzana","1 cucharadita de orégano mexicano","1/2 cucharadita de comino molido","3 clavos de olor","1 raja pequeña de canela","2 cucharaditas de sal","2 hojas de laurel","2 tazas (500 ml) de agua, y 1 taza (250 ml) más para licuar","16 tortillas de maíz","250 g de queso Oaxaca deshebrado","Cebolla y cilantro picados, y limón, para servir"]', '["Tuesta los chiles en un comal 20 a 30 segundos por lado y remójalos 15 minutos en agua caliente. Hierve los jitomates 5 minutos.","Licúa los chiles escurridos con los jitomates, la cebolla, el ajo, el vinagre, el orégano, el comino, los clavos, la canela, la sal y 1 taza (250 ml) de agua hasta que quede liso. Cuela.","Unta la carne con la salsa en un recipiente y refrigérala al menos 1 hora y hasta una noche. No la dejes a temperatura ambiente.","Calienta el horno a 160°C. Pasa la carne con toda la salsa a una olla con tapa, agrega el laurel y 2 tazas (500 ml) de agua. Tapa bien y hornea 3 horas, hasta que la carne se deshaga con un tenedor.","Retira la carne y deshebra. Cuela el caldo, quítale la grasa roja de la superficie y reserva esa grasa. Mantén el caldo (consomé) caliente y ajusta la sal.","Moja cada tortilla en la grasa reservada y ponla en un comal caliente. Agrega queso y carne a la mitad, dobla y dora 1 a 2 minutos por lado.","Sirve los tacos con cebolla, cilantro y limón, y una taza de consomé caliente para mojar."]', 'draft');
